package org.marketreview.nativeapp;
import org.json.*;import java.io.File;import java.nio.file.Files;import java.nio.charset.StandardCharsets;
final class MaterialLibraryChecks {
 interface Work{void run()throws Exception;}static void check(boolean b,String why){if(!b)throw new AssertionError(why);}static void refuses(Work work)throws Exception{boolean failed=false;try{work.run();}catch(Exception e){failed=true;}check(failed,"expected refusal");}
 static JSONObject descriptor(String kind,String id,String text)throws Exception{return new JSONObject().put("kind",kind).put("id",id).put("row",new JSONObject().put("id",id).put("title","材料"+id).put("text",text).put("originalText","原始正文").put("author","测试作者").put("sourceType","article").put("topic","原主题").put("publishedAt","2000-01-01").put("updatedAt","2000-01-01").put("legacyOriginal",new JSONObject().put("id",123)));}
 static JSONObject model()throws Exception{JSONObject d=descriptor("docs","same","完整原文"),c=descriptor("collections","same","不同类型同ID"),m=MaterialLibraryModel.material(d),ref=m.getJSONObject("reference");check(MaterialLibraryModel.materials(new JSONArray().put(d).put(c)).length()==2,"kind namespace");refuses(()->MaterialLibraryModel.materials(new JSONArray().put(d).put(d)));refuses(()->MaterialLibraryModel.resolve(ref,new JSONArray().put(d).put(d)));check(MaterialLibraryModel.resolve(ref,new JSONArray().put(d)).getString("id").equals("same"),"docs exact sourceKind normalization");JSONObject urlD=new JSONObject(d.toString());urlD.getJSONObject("row").put("sourceUrl","https://example.com/article?id=1");JSONObject urlRef=MaterialLibraryModel.material(urlD).getJSONObject("reference");urlD.getJSONObject("row").put("sourceUrl","https://example.com/article?id=2");refuses(()->MaterialLibraryModel.resolve(urlRef,new JSONArray().put(urlD)));JSONObject changed=new JSONObject(d.toString());changed.getJSONObject("row").put("text","changed");refuses(()->MaterialLibraryModel.resolve(ref,new JSONArray().put(changed)));refuses(()->MaterialLibraryModel.resolve(ref,new JSONArray()));JSONArray all=new JSONArray();for(int i=0;i<601;i++)all.put(descriptor("docs",""+i,"尾段"+i));check(MaterialLibraryModel.filter(MaterialLibraryModel.materials(all),new JSONObject().put("search","尾段600"),new JSONObject()).length()==1,"beyond500 full search");JSONObject r=MaterialLibraryModel.classification(ref,"人工观察",new JSONArray().put("tag;literal"),"完整笔记","");MaterialLibraryModel.validate(r);refuses(()->MaterialLibraryModel.classification(ref,"",new JSONArray().put("重复").put("重复"),"",""));return r;}
 public static void main(String[] args)throws Exception{JSONObject r=model();if(args.length>0)Files.write(new File(args[0]).toPath(),MaterialLibraryModel.json(r).getBytes(StandardCharsets.UTF_8));System.out.println("PASS MaterialLibrary production Java exact docs/kind namespace/full601 search/changed missing refusal/manual labels; model only");}
 static void run(FlowInstrumentation f)throws Exception{JSONObject r=model();File file=f.activity.getDatabasePath("material-library-checks-"+System.nanoTime()+".sqlite");MaterialLibraryStore s=new MaterialLibraryStore(file);s.save(r,"");JSONObject ref=r.getJSONObject("reference"),newer=MaterialLibraryModel.classification(ref,"后续分类",new JSONArray(),"新笔记",r.getString("id"));s.save(newer,r.getString("id"));refuses(()->s.save(r,""));String backup=s.backup();JSONObject preview=s.preview(backup);check(s.history().length()==2,"preview/cancel no write");MaterialLibraryStore copy=new MaterialLibraryStore(f.activity.getDatabasePath("material-library-copy-"+System.nanoTime()+".sqlite"));copy.merge(preview);check(copy.history().length()==2,"durable classification copy");String large="大材料正文".repeat(240000);JSONObject largeD=descriptor("docs","large",large),largeRef=MaterialLibraryModel.material(largeD).getJSONObject("reference"),largeR=MaterialLibraryModel.classification(largeRef,"人工",new JSONArray(),"笔记","");s.save(largeR,"");check(s.heads().getJSONObject(MaterialLibraryModel.key(largeRef)).getJSONObject("reference").getJSONObject("snapshot").getString("text").equals(large),"large payload chunk read");String rev=s.saveState(new JSONObject().put("notes",large),"");refuses(()->s.saveState(new JSONObject(),"stale"));check(s.state().getString("notes").equals(large),"large private state read");f.ui(()->{try{MaterialLibraryScreen screen=new MaterialLibraryScreen(f.activity,f.activity.getDatabasePath("material-library-ui-"+System.nanoTime()+".sqlite"),()->new JSONArray().put(largeD),null);screen.choose(screen.all.getJSONObject(0));screen.category.setText("recreated classification draft");MaterialLibraryScreen reopened=new MaterialLibraryScreen(f.activity,screen.store.file,()->new JSONArray().put(largeD),null);check(reopened.category.getText().toString().equals("recreated classification draft")&&reopened.body.getText().toString().contains(large),"draft/fullbody reopening");reopened.setDarkTheme(true);check(reopened.back()&&!reopened.back(),"internal back");}catch(Exception e){throw new RuntimeException(e);}});}
}


